import{_ as a,o as t,c as r,a0 as n}from"./chunks/framework.D4fUSYzX.js";const u=JSON.parse('{"title":"The operator pages carry usage, and the ADRs carry the mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0081-the-operator-pages-carry-usage-and-the-adrs-carry-the-mechanics.md","filePath":"adr/0081-the-operator-pages-carry-usage-and-the-adrs-carry-the-mechanics.md"}'),s={name:"adr/0081-the-operator-pages-carry-usage-and-the-adrs-carry-the-mechanics.md"};function o(i,e,h,c,d,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="the-operator-pages-carry-usage-and-the-adrs-carry-the-mechanics" tabindex="-1">The operator pages carry usage, and the ADRs carry the mechanics <a class="header-anchor" href="#the-operator-pages-carry-usage-and-the-adrs-carry-the-mechanics" aria-label="Permalink to &quot;The operator pages carry usage, and the ADRs carry the mechanics&quot;">​</a></h1><p>Status: accepted.</p><p>The documentation site&#39;s operator guides (Getting Started, Operation, Work flow, and Configuration) grew into an implementation write-up: internal mechanics - the queue&#39;s pickup and top-up, state-file internals, seat counts, label-write convergence - and ADR references on nearly every line. The maintainer wants the site to focus on usage, from the operator&#39;s standpoint. We decided the operator pages carry usage only - what the operator does, what the operator sees, and at most a one-to-two sentence &quot;why&quot; note where the operator gets confused - and the mechanics stay in the ADRs, which remain published.</p><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li>Keep the ADR references in the operator pages for traceability. Rejected: the references did not stop the pages growing, and the traceability already lives in the ADRs and the code, so the operator paid for nothing.</li><li>Move the contributor content (the Development pages and the ADRs) out of the published site. Rejected: one site and one build. The ADRs are a trust signal for a visitor. The rewrite keeps them published, de-emphasized under a single Contributing entry, so the operator path is the front face.</li><li>Restructure the operator pages into task-oriented guides. Rejected: the Operation pages are a control reference, not a task list. The rewrite keeps each page&#39;s shape and cuts the internals.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>An edit that re-adds an ADR reference or a paragraph of mechanics to an operator page is a regression against this ADR, not an improvement.</li><li>The content conventions doc carries this rule, so the next agent edit keeps it.</li><li>The deep detail is not deleted by the rewrite; it stands in the ADRs and the configuration key reference.</li><li>The rewrite itself lands per issue #189.</li></ul>',7)])])}const g=a(s,[["render",o]]);export{u as __pageData,g as default};
